      <div style="display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--bd)"><div style="padding:9px 14px;font-size:13px;color:var(--gold);font-family:var(--mono);border-right:1px solid var(--bd)">last week</div><div style="padding:9px 14px;font-size:13px;color:var(--brit-green);font-family:var(--mono)">the previous week / the week before</div></div>
